export type Language = 'en' | 'zh';

export type NutrientInfo = {
  name: string;
  description: string;
  benefits: string[];
  sources: string[];
  unit: string;
  dailyValue: number;
};

export type NutrientDataByLanguage = {
  [key: string]: NutrientInfo;
};

export function getNutrientInfo(name: string, language: Language): NutrientInfo | undefined {
  return (nutrientData[language] as NutrientDataByLanguage)?.[name];
}
